// Package cardgen renders the corpus's generated card spellings.
// The generator and freshness gate use the same renderer, which reads
// statements from the registry and validates them without consulting
// the generated data or constructing a proof engine.
package cardgen

import (
	"bytes"
	"fmt"
	"go/format"
	"runtime"
	"sort"
	"sync"

	"github.com/euc-ai/xugo/engine"
	"github.com/euc-ai/xugo/library/carddata"
	"github.com/euc-ai/xugo/library/registry"
)

// File is the generated file in library/carddata.
const File = "cards_gen.go"

// Render computes the cards' keys and both spellings, validates each
// registered key, and renders the table in entry-name order. Generating
// the typed spelling checks its parse round-trip at the statement door;
// an empty typed spelling means that door reads no print of the card.
func Render() []byte {
	var entries []*registry.ProofEntry
	for _, entry := range registry.All() {
		if entry.IsCard() {
			entries = append(entries, entry)
		}
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Name < entries[j].Name })
	texts := make([]carddata.Text, len(entries))
	next := make(chan int)
	var wg sync.WaitGroup
	for range runtime.GOMAXPROCS(0) {
		wg.Go(func() {
			for i := range next {
				entry := entries[i]
				key := string(entry.Statement().Key())
				if key != entry.Key {
					panic(fmt.Sprintf("cardgen: %s has key %s, its statement has %s — run TestEntryKeyIsOwnKey", entry.Name, entry.Key, key))
				}
				texts[i] = carddata.Text{Key: key, Statement: entry.StatementText(), StatementTyped: engine.EntryStatementTyped(entry)}
			}
		})
	}
	for i := range entries {
		next <- i
	}
	close(next)
	wg.Wait()

	var b bytes.Buffer
	fmt.Fprintln(&b, "// Code generated by card_data_gen; DO NOT EDIT.")
	fmt.Fprintln(&b, "\npackage carddata\n\nfunc init() {\ntexts = map[string]Text{")
	for i, entry := range entries {
		text := texts[i]
		fmt.Fprintf(&b, "%q: {Key: %q, Statement: %q, StatementTyped: %q},\n", entry.Name, text.Key, text.Statement, text.StatementTyped)
	}
	fmt.Fprintln(&b, "}\n}")
	out, err := format.Source(b.Bytes())
	if err != nil {
		panic(fmt.Sprintf("cardgen: invalid generated Go: %v", err))
	}
	return out
}
